from functools import lru_cache, cache
import sys

# Naive recursive — O(2^n)
def fib_naive(n: int) -> int:
    if n <= 1: return n
    return fib_naive(n-1) + fib_naive(n-2)

# Memoized — O(n) with lru_cache
@cache
def fib_memo(n: int) -> int:
    if n <= 1: return n
    return fib_memo(n-1) + fib_memo(n-2)

# Bottom-up — O(n) time, O(1) space
def fib_dp(n: int) -> int:
    if n <= 1: return n
    a, b = 0, 1
    for _ in range(2, n+1):
        a, b = b, a + b
    return b

# Coin change — minimum coins to make amount
@cache
def coin_change(coins: tuple[int, ...], amount: int) -> int:
    if amount == 0: return 0
    if amount < 0: return float('inf')
    return 1 + min(coin_change(coins, amount - c) for c in coins)

# Note: list must be converted to tuple for hashability
coins_list = [1, 5, 10]
result = coin_change(tuple(coins_list), 27)

# Bottom-up coin change — avoids recursion limit
def coin_change_dp(coins: list[int], amount: int) -> int:
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                dp[a] = min(dp[a], 1 + dp[a - c])
    return dp[amount] if dp[amount] != float('inf') else -1

# Increase recursion limit for deep problems (use carefully)
sys.setrecursionlimit(10000)
